import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Security","description":"","frontmatter":{},"headers":[],"relativePath":"guide/security.md","filePath":"guide/security.md","lastUpdated":1787093302000}`),a={name:`guide/security.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="security" tabindex="-1">Security <a class="header-anchor" href="#security" aria-label="Permalink to “Security”">​</a></h1><h2 id="trust-model" tabindex="-1">Trust model <a class="header-anchor" href="#trust-model" aria-label="Permalink to “Trust model”">​</a></h2><p>The credentials are the web login of a Calibre-Web user. Compromising them grants whatever that account may do in the web UI — this server only ever reads the OPDS feed, but the credentials themselves are not limited to that. So:</p><ul><li><strong>Use a dedicated account</strong> with only the View and Download roles. Never the admin login.</li><li>Treat every environment variable this server reads as a secret.</li><li>The MCP client, and therefore the model driving it, sees every tool result. Do not point this server at a library whose metadata you would not put into a model&#39;s context.</li></ul><h2 id="read-only-by-construction" tabindex="-1">Read-only by construction <a class="header-anchor" href="#read-only-by-construction" aria-label="Permalink to “Read-only by construction”">​</a></h2><p>There is no read-only <em>mode</em> — there is nothing else. The server registers six tools, all annotated <code>readOnlyHint</code>, all GET requests. It keeps no state, writes no files, and has no confirmation flows because there is nothing to confirm.</p><h2 id="transport" tabindex="-1">Transport <a class="header-anchor" href="#transport" aria-label="Permalink to “Transport”">​</a></h2><ul><li><strong>Redirects are refused</strong> (<code>redirect: &#39;error&#39;</code>). Basic credentials are resent by default on redirects; refusing them means the header can never be replayed to a host you did not configure.</li><li>Every request carries a 30-second timeout that also covers body streaming.</li><li>Insecure TLS, when enabled, is scoped to the configured origin — see <a href="/guide/configuration">Configuration</a>.</li></ul><h2 id="the-xml-pipeline" tabindex="-1">The XML pipeline <a class="header-anchor" href="#the-xml-pipeline" aria-label="Permalink to “The XML pipeline”">​</a></h2><p>OPDS is Atom XML, and XML parsers have a long history of being the hole. This one is deliberately dumb:</p><ul><li>Documents declaring a <code>DOCTYPE</code> or <code>ENTITY</code> are <strong>refused before parsing</strong> — a legitimate Calibre-Web feed never contains one, and this closes entity expansion for good, independent of parser defaults.</li><li>Entity processing in the parser is off; the five XML built-ins and numeric references are decoded by this server&#39;s own code, which refuses control characters (C0 and C1) and looks entities up in a null-prototype map, so <code>&amp;constructor;</code> resolves to nothing instead of <code>Object.prototype</code>.</li><li>Value coercion is off — a book titled &quot;1984&quot; stays a string.</li><li>Deeply nested and oversized documents are rejected (the parser enforces a nesting cap; an 8 MB streaming cap sits in front of it).</li></ul><h2 id="untrusted-metadata" tabindex="-1">Untrusted metadata <a class="header-anchor" href="#untrusted-metadata" aria-label="Permalink to “Untrusted metadata”">​</a></h2><p>Book titles, authors, tags, series and summaries were written by publishers, scrapers, or whoever filled the library. Every result that carries them:</p><ul><li>includes an explicit note that this is untrusted data, not instructions,</li><li>has control characters and BiDi override characters stripped (the Trojan-Source primitive),</li><li>and only contains URLs that resolve to the <strong>configured origin</strong> over http(s) — a hostile feed cannot plant <code>javascript:</code>, <code>file:</code> or cross-origin links into the model context as legitimate-looking library URLs.</li></ul><p>Covers are only passed through for real raster image types (JPEG, PNG, GIF, WebP); SVG — active content — and anything mislabelled is refused.</p><h2 id="reporting" tabindex="-1">Reporting <a class="header-anchor" href="#reporting" aria-label="Permalink to “Reporting”">​</a></h2><p>Please use <a href="https://github.com/ni-c/calibreweb-mcp/security/advisories/new" target="_blank" rel="noreferrer">GitHub private vulnerability reporting</a> — see <a href="https://github.com/ni-c/calibreweb-mcp/blob/main/SECURITY.md" target="_blank" rel="noreferrer">SECURITY.md</a>.</p>`,17)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};